    public static PrecisProperty Property(int point) => Find(PropertyData, point, PrecisProperty.Disallowed);
    public static PrecisBidi Bidi(int point) => Find(BidiData, point, PrecisBidi.Other);
    public static PrecisJoining Joining(int point) => Find(JoiningData, point, PrecisJoining.Other);
    public static PrecisScript Script(int point) => Find(ScriptData, point, PrecisScript.Other);
    public static bool IsVirama(int point) => Find(ViramaData, point, false);
    public static string? Width(int point) => Map(WidthData, WidthValues, point);
    public static string? Lower(int point) => Map(LowerData, LowerValues, point);

    private static T Find<T>(ReadOnlySpan<PrecisRange<T>> ranges, int point, T fallback) {
        var low = 0;
        var high = ranges.Length - 1;
        while (low <= high) {
            var middle = low + (high - low) / 2;
            var range = ranges[middle];
            if (point < range.Start) high = middle - 1;
            else if (point > range.End) low = middle + 1;
            else return range.Value;
        }
        return fallback;
    }

    private static string? Map(ReadOnlySpan<int> points, ReadOnlySpan<string> values, int point) {
        var index = points.BinarySearch(point);
        return index < 0 ? null : values[index];
    }
